import{_ as t,o as r,c as a,a2 as l}from"./chunks/framework.A5mep7Fe.js";const p=JSON.parse('{"title":"⌨️ 03 · 高频手撕代码题","description":"","frontmatter":{},"headers":[],"relativePath":"09-面试实战/03-高频手撕代码题.md","filePath":"09-面试实战/03-高频手撕代码题.md","lastUpdated":1786806808000}'),n={name:"09-面试实战/03-高频手撕代码题.md"};function i(s,o,e,g,d,h){return r(),a("div",null,[...o[0]||(o[0]=[l('<h1 id="⌨️-03-·-高频手撕代码题" tabindex="-1">⌨️ 03 · 高频手撕代码题 <a class="header-anchor" href="#⌨️-03-·-高频手撕代码题" aria-label="Permalink to &quot;⌨️ 03 · 高频手撕代码题&quot;">​</a></h1><blockquote><p>算法/工程岗都躲不开。本篇列最常考 + 思路，配合 LeetCode 练习。重点不是背答案，是<strong>写对 + 讲清复杂度</strong>。</p></blockquote><hr><h2 id="一、数据结构与算法-通用" tabindex="-1">一、数据结构与算法（通用） <a class="header-anchor" href="#一、数据结构与算法-通用" aria-label="Permalink to &quot;一、数据结构与算法（通用）&quot;">​</a></h2><ol><li><strong>两数之和 / 三数之和</strong>：哈希 / 双指针，O(n) / O(n²)</li><li><strong>反转链表 / 快慢指针</strong>：环检测、中点</li><li><strong>二叉树遍历</strong>：前中后序（递归+迭代）、层序（队列）</li><li><strong>Top-K 问题</strong>：堆（O(n log k)）、快选（O(n) 期望）</li><li><strong>LRU 缓存</strong>：哈希 + 双向链表</li><li><strong>最长子串/子序列</strong>：滑动窗口、DP</li><li><strong>岛屿数量 / 连通块</strong>：DFS/BFS、并查集</li></ol><h2 id="二、ai-算法岗特化-常让现场实现" tabindex="-1">二、AI 算法岗特化（常让现场实现） <a class="header-anchor" href="#二、ai-算法岗特化-常让现场实现" aria-label="Permalink to &quot;二、AI 算法岗特化（常让现场实现）&quot;">​</a></h2><ol><li><strong>实现 Scaled Dot-Product Attention</strong>：QK^T / √d → softmax → ×V；注意 mask 与数值稳定</li><li><strong>实现 RoPE 旋转</strong>：对 (x2i, x2i+1) 做 2D 旋转</li><li><strong>实现 LoRA 前向</strong>：Wx + (BA)x，低秩增量</li><li><strong>Softmax（数值稳定）</strong>：减最大值防溢出</li><li><strong>交叉熵损失 + 反向</strong>：推导并实现</li><li><strong>简单 K-Means / KNN</strong>：距离计算、迭代</li><li><strong>Top-p / Top-k 采样</strong>：按概率截断采样</li><li><strong>RAG 检索 Top-k</strong>：向量相似度排序取前 k（可用堆）</li></ol><h2 id="三、系统设计-开发-平台岗" tabindex="-1">三、系统设计（开发/平台岗） <a class="header-anchor" href="#三、系统设计-开发-平台岗" aria-label="Permalink to &quot;三、系统设计（开发/平台岗）&quot;">​</a></h2><ol><li><strong>设计一个 LLM 对话 API（含流式）</strong>：网关→模型→SSE 转发、限流、缓存、降级</li><li><strong>设计一个 RAG 系统</strong>：ETL→切片→嵌入→检索→重排→生成，讲吞吐/一致性/成本</li><li><strong>设计一个短链/高并发计数服务</strong>：分片、缓存、一致性</li><li><strong>设计限流</strong>：令牌桶/漏桶</li></ol><h2 id="四、答题套路-保分" tabindex="-1">四、答题套路（保分） <a class="header-anchor" href="#四、答题套路-保分" aria-label="Permalink to &quot;四、答题套路（保分）&quot;">​</a></h2><ol><li><strong>澄清</strong>：输入规模、边界、是否允许额外空间</li><li><strong>说思路</strong>：暴力 → 优化，讲复杂度</li><li><strong>写代码</strong>：清晰命名、注释关键点</li><li><strong>测边界</strong>：空输入、极值、重复</li><li><strong>分析</strong>：时间/空间复杂度，可优化点</li></ol><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q：手撕 Attention 要注意什么？</strong></p><blockquote><p>数值稳定（softmax 减 max）、mask（padding/因果）、维度对齐（QK 同维）、√d 缩放、与 V 的乘积累加。能写对并解释即过关。</p></blockquote><p><strong>Q：为什么考 LRU？</strong></p><blockquote><p>经典「哈希+链表」组合，考察数据结构熟练度与边界处理，也是模型 KV Cache 常用的淘汰策略原型。</p></blockquote><hr><p>➡️ 下一步：<a href="./04-STAR面试稿">04-STAR面试稿</a></p>',18)])])}const _=t(n,[["render",i]]);export{p as __pageData,_ as default};
